mapper.select:
SELECT s.id, s.user_id, u.name AS cashier_name, s.total_amount, s.real_amount, s.change_amount, IFNULL(s.order_num, CONCAT('SO', LPAD(s.id, 8, '0'))) AS order_num, s.create_time, CASE WHEN sr.id IS NOT NULL AND sr.status = 1 THEN 2 WHEN sr.id IS NOT NULL AND sr.status = 0 THEN 1 ELSE 0 END AS return_status, s.payment_method, s.status FROM sales s LEFT JOIN user u ON s.user_id = u.id LEFT JOIN sales_return sr ON s.id = sr.sales_id
AND (s.order_num LIKE CONCAT('%', #{orderNum}, '%') OR CONCAT('SO', LPAD(s.id, 8, '0')) LIKE CONCAT('%', #{orderNum}, '%'))
AND s.create_time >= #{startDate}
AND s.create_time <= #{endDate}
AND s.user_id = #{userId}
ORDER BY s.create_time DESC

SELECT COUNT(*) AS cnt, IFNULL(SUM(s.total_amount), 0) AS total_amount, IFNULL(SUM(s.real_amount), 0) AS real_amount, IFNULL(SUM(EXISTS(SELECT 1 FROM sales_return sr WHERE sr.sales_id = s.id)), 0) AS return_count, IFNULL(SUM(EXISTS(SELECT 1 FROM sales_return sr WHERE sr.sales_id = s.id AND sr.status = 1)), 0) AS return_done_count, IFNULL(SUM(EXISTS(SELECT 1 FROM sales_return sr WHERE sr.sales_id = s.id AND sr.status = 0)), 0) AS return_pending_count FROM sales s
AND (s.order_num LIKE CONCAT('%', #{orderNum}, '%') OR CONCAT('SO', LPAD(s.id, 8, '0')) LIKE CONCAT('%', #{orderNum}, '%'))
AND s.create_time >= #{startDate}
AND s.create_time <= #{endDate}
AND s.user_id = #{userId}
